PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS "add_catagory" (   "id" INTEGER PRIMARY KEY AUTOINCREMENT,   "categoryName" TEXT,   "categoryInfo" TEXT,   "categoryImage" TEXT );
CREATE TABLE IF NOT EXISTS "e_apply_job" (   "a_id" INTEGER PRIMARY KEY AUTOINCREMENT,   "job_id" TEXT,   "job_title" TEXT,   "job_type" TEXT,   "company" TEXT,   "location" TEXT,   "salary" TEXT,   "image" TEXT,   "applay_date" TEXT,   "user_id" TEXT,   "name" TEXT,   "mobilenumber" INTEGER,   "email" TEXT,   "resume" TEXT,   "status" TEXT,   "r_id" TEXT,   "interview_date" TEXT,   "interview_time" TEXT,   "interview_location" TEXT );
CREATE TABLE IF NOT EXISTS "e_contactus" (   "e_id" INTEGER PRIMARY KEY AUTOINCREMENT,   "name" TEXT,   "contactnumber" INTEGER,   "email" TEXT,   "message" TEXT );
CREATE TABLE IF NOT EXISTS "e_feedback" (   "e_id" INTEGER PRIMARY KEY AUTOINCREMENT,   "name" TEXT,   "email" TEXT,   "rating" TEXT,   "feedback" TEXT,   "date" TEXT );
CREATE TABLE IF NOT EXISTS "e_signup" (   "id" INTEGER PRIMARY KEY AUTOINCREMENT,   "fullname" TEXT,   "username" TEXT,   "email" TEXT,   "gender" TEXT,   "phone_no" TEXT,   "password" TEXT,   "photo" TEXT );
CREATE TABLE IF NOT EXISTS "interview_schedule" ( "interview_id" INTEGER PRIMARY KEY AUTOINCREMENT, "a_id" TEXT, "candudate_name" TEXT, "interview_time" TEXT, "interview_date" TEXT, "interview_location" TEXT, "status" TEXT );
CREATE TABLE IF NOT EXISTS "r_add_job" (   "job_id" INTEGER PRIMARY KEY AUTOINCREMENT,   "category" TEXT,   "jobtitle" TEXT,   "companyname" TEXT,   "JobType" TEXT,   "position" TEXT,   "Experience" TEXT,   "Qualification" TEXT,   "location" TEXT,   "salary" TEXT,   "job_discription" TEXT,   "companylogo" TEXT,   "requirement" TEXT,   "job_upload_date" TEXT,   "r_id" TEXT );
CREATE TABLE IF NOT EXISTS "r_signup" (   "r_id" INTEGER PRIMARY KEY AUTOINCREMENT,   "fullname" TEXT,   "companyname" TEXT,   "email" TEXT,   "password" TEXT,   "gender" TEXT,   "phone_no" INTEGER,   "address" TEXT,   "photo" TEXT );
